import { useSelector } from 'react-redux';
import { selectDarkMode } from '../store/slices/uiSlice';

/**
 * Returns a `t(darkClass, lightClass)` helper and the raw darkMode boolean.
 * Usage:  const { t, dark } = useTheme();
 *         className={t('text-white', 'text-black')}
 */
export function useTheme() {
  const dark = useSelector(selectDarkMode);
  const t = (darkClass, lightClass) => (dark ? darkClass : lightClass);

  // Convenient grouped tokens
  const tokens = {
    bg:      t('bg-[#22223A]',  'bg-[#f8f7ff]'),
    sidebar: t('bg-[#22223A]',  'bg-[#f0f0fa]'),
    chat:    t('bg-[#22223A]',  'bg-white'),
    card:    t('bg-[#2B2B48]',  'bg-white'),
    input:   t('bg-[#30304F]',  'bg-[#f4f4fc]'),
    border:  t('border-[#414165]', 'border-[#e0e0f0]'),
    text:    t('text-[#e8e8f0]', 'text-[#1a1a2e]'),
    muted:   'text-[#7878a0]',
    hover:   t('hover:bg-[#30304F]', 'hover:bg-[#eeeeff]'),
    msgBot:  t('bg-[#2B2B48]',  'bg-[#f3f3ff]'),
    // raw hex values (for inline styles)
    textHex:   t('#e8e8f0', '#1a1a2e'),
    mutedHex:  '#7878a0',
    borderHex: t('#414165', '#e0e0f0'),
    inputHex:  t('#30304F', '#f4f4fc'),
    hoverHex:  t('#30304F', '#eeeeff'),
    bgHex:     t('#22223A', '#f8f7ff'),
    sidebarHex:t('#22223A', '#f0f0fa'),
    chatHex:   t('#22223A', '#ffffff'),
    cardHex:   t('#2B2B48', '#ffffff'),
    msgBotHex: t('#2B2B48', '#f3f3ff'),
  };

  return { dark, t, ...tokens };
}
